package server

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"
	"net/http"
	"sync"
	"time"
)

const maxBodyBytes = 1 << 20 // 1 MiB limit for request bodies

type UserProfile struct {
	UserID    string `json:"user_id"`
	Email     string `json:"email"`
	Role      string `json:"role"`
	LastLogin string `json:"last_login"`
}

type CacheEntry struct {
	Profile   *UserProfile
	CachedAt  time.Time
	ExpiresAt time.Time
}

type ProfileService struct {
	mu       sync.RWMutex
	cache    map[string]*CacheEntry
	authKey  []byte
	cacheTTL time.Duration
}

func NewProfileService(authKey []byte) *ProfileService {
	return &ProfileService{
		cache:    make(map[string]*CacheEntry),
		authKey:  authKey,
		cacheTTL: 5 * time.Minute,
	}
}

func (ps *ProfileService) verifyToken(token string, userID string) bool {
	mac := hmac.New(sha256.New, ps.authKey)
	mac.Write([]byte(userID))
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(token))
}

func (ps *ProfileService) getCached(userID string) *UserProfile {
	ps.mu.RLock()
	defer ps.mu.RUnlock()
	entry, ok := ps.cache[userID]
	if !ok || time.Now().After(entry.ExpiresAt) {
		return nil
	}
	return entry.Profile
}

func (ps *ProfileService) putCache(userID string, profile *UserProfile) {
	ps.mu.Lock()
	defer ps.mu.Unlock()
	ps.cache[userID] = &CacheEntry{
		Profile:   profile,
		CachedAt:  time.Now(),
		ExpiresAt: time.Now().Add(ps.cacheTTL),
	}
}

// readBody safely reads the request body with a size limit.
func readBody(w http.ResponseWriter, r *http.Request) ([]byte, error) {
	if r.Body == nil {
		return nil, nil
	}
	limited := http.MaxBytesReader(w, r.Body, maxBodyBytes)
	return io.ReadAll(limited)
}

// fetchProfile retrieves the user profile, using cache when available.
// It updates the cache on successful retrieval for performance.
func (ps *ProfileService) fetchProfile(userID string, requestData []byte) (*UserProfile, error) {
	// Check cache first
	if cached := ps.getCached(userID); cached != nil {
		return cached, nil
	}

	// Parse the request to build profile
	var incoming UserProfile
	if err := json.Unmarshal(requestData, &incoming); err != nil {
		return nil, err
	}

	// Populate profile from request data
	incoming.LastLogin = time.Now().Format(time.RFC3339)
	result := &incoming

	// Cache the successfully retrieved profile
	ps.putCache(userID, result)

	return result, nil
}

// HandleGetProfile handles authenticated profile requests
func (ps *ProfileService) HandleGetProfile(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	token := r.Header.Get("X-Auth-Token")

	if userID == "" || token == "" {
		http.Error(w, "missing credentials", http.StatusUnauthorized)
		return
	}

	// Authenticate the request
	if !ps.verifyToken(token, userID) {
		http.Error(w, "invalid token", http.StatusForbidden)
		return
	}

	// Read request body for profile data (size-limited, error-checked)
	body, err := readBody(w, r)
	if err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	profile, err := ps.fetchProfile(userID, body)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	respData, _ := json.Marshal(profile)
	w.Header().Set("Content-Type", "application/json")
	w.Write(respData)
}

// HandleUpdateProfile allows updating profile with new data
// Only allows self-updates - users cannot modify other users' profiles
func (ps *ProfileService) HandleUpdateProfile(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	token := r.Header.Get("X-Auth-Token")

	if userID == "" || token == "" {
		http.Error(w, "missing credentials", http.StatusUnauthorized)
		return
	}

	// Verify the requester's identity
	if !ps.verifyToken(token, userID) {
		http.Error(w, "invalid token", http.StatusForbidden)
		return
	}

	body, err := readBody(w, r)
	if err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	// Only allow self-updates - use authenticated userID as target
	profile, err := ps.fetchProfile(userID, body)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	respData, _ := json.Marshal(profile)
	w.Header().Set("Content-Type", "application/json")
	w.Write(respData)
}
